function renderLessonList(){const trio=state.mode==='trio',sets=trio?LESSONS:SYN_LESSONS,current=trio?state.lesson:state.synLesson,list=$('#lessons'),mobile=$('#mobileLessons');document.querySelector('.sidebar-head h2').textContent=trio?'Bài ghép bộ 3':'Bài từ đồng nghĩa';document.querySelector('.total').textContent=`${sets.length} bài`;document.querySelectorAll('.mode-choice').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));list.innerHTML='';mobile.innerHTML='';sets.forEach((lesson,i)=>{const s=trio?lessonStats(i):synLessonStats(i),b=document.createElement('button');b.className='lesson'+(current===i?' active':'');b.innerHTML=`<div class="lesson-line"><span>Bài ${String(i+1).padStart(2,'0')}</span><span class="lesson-count">${lesson.length} ${trio?'từ':'cặp'}</span></div><div class="mini-stats"><span>Lượt <b>${s.plays}</b></span><span>Đúng <b>${s.correct}</b></span><span>Sai <b>${s.wrong}</b></span></div>`;b.onclick=()=>selectLesson(i);list.appendChild(b);const o=document.createElement('option');o.value=i;o.textContent=`Bài ${String(i+1).padStart(2,'0')} · ${lesson.length} ${trio?'từ':'cặp'}`;o.selected=i===current;mobile.appendChild(o)})}
