function createFreshOrder(){const old=wordOrder,groups=LESSONS.length;for(let attempt=0;attempt<200;attempt++){const candidate=shuffle([...Array(DATA.length).keys()]);let mixed=true;for(let g=0;g<groups;g++){const oldSet=new Set(old.slice(g*SIZE,(g+1)*SIZE)),overlap=candidate.slice(g*SIZE,(g+1)*SIZE).filter(x=>oldSet.has(x)).length;if(overlap>3){mixed=false;break}}if(mixed)return candidate}return shuffle([...Array(DATA.length).keys()])}
function createFreshSynOrder(){for(let attempt=0;attempt<200;attempt++){const candidate=shuffle([...Array(SYNONYMS.length).keys()]);let mixed=true;for(let g=0;g<SYN_LESSONS.length;g++){const oldSet=new Set(synOrder.slice(g*SIZE,(g+1)*SIZE)),overlap=candidate.slice(g*SIZE,(g+1)*SIZE).filter(x=>oldSet.has(x)).length;if(overlap>4){mixed=false;break}}if(mixed)return candidate}return shuffle([...Array(SYNONYMS.length).keys()])}
function applyShuffle(){wordOrder=createFreshOrder();synOrder=createFreshSynOrder();localStorage.setItem(ORDER_KEY,JSON.stringify(wordOrder));localStorage.setItem(SYN_ORDER_KEY,JSON.stringify(synOrder));stats={lessons:{},synLessons:{}};localStorage.setItem(storeKey,JSON.stringify(stats));LESSONS=makeLessons(wordOrder);SYN_LESSONS=makeSynLessons(synOrder);state.lesson=0;state.synLesson=0;state.mode='trio';state.started=false;state.matched=new Set();state.selected={word:null,meaning:null,example:null};state.locked=false;state.synStarted=false;state.synRound=0;state.synRoundOrder=[];state.synSelected=[];state.synPair=null;switchMode('trio');randomBtn.textContent='✓ Đã chia lại cả 2 chế độ';setTimeout(()=>randomBtn.textContent='⤨ Xáo bộ từ mới',1800)}
function resetAndShuffle(){if(!window.confirm(`Xáo lại cả ${LESSONS.length} bài Ghép bộ 3 và ${SYN_LESSONS.length} bài Từ đồng nghĩa? Toàn bộ lượt chơi, số lần đúng và sai hiện tại sẽ bị xóa.`))return;applyShuffle()}
const randomStyle=document.createElement('style');randomStyle.textContent='.random-btn{border:1px solid #ffd45e66;background:#ffd45e16;color:var(--yellow);border-radius:12px;padding:10px 14px;font-weight:800;cursor:pointer;white-space:nowrap;transition:.18s}.random-btn:hover{background:#ffd45e28;transform:translateY(-1px)}.mode-nav{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:16px;padding:4px;background:#0e142b;border:1px solid var(--line);border-radius:14px}.mode-choice{border:0;background:transparent;color:var(--muted);border-radius:10px;padding:10px 6px;font-size:.78rem;font-weight:800;cursor:pointer;line-height:1.25}.mode-choice.active{background:var(--purple);color:#fff;box-shadow:0 6px 18px #6e57ff44}.mode-choice small{display:block;margin-top:3px;font-size:.7rem;opacity:.8}@media(min-width:901px){.game-head .tabs{display:none}}@media(max-width:900px){.sidebar .mode-nav{display:none}}@media(max-width:700px){.topbar{flex-wrap:wrap}.random-btn{width:100%;order:3}.sound-tip{margin-left:auto}}';document.head.appendChild(randomStyle);
const modeNav=document.createElement('div');modeNav.className='mode-nav';modeNav.innerHTML=`<button class="mode-choice active" data-mode="trio">Ghép bộ 3<small>${LESSONS.length} bài</small></button><button class="mode-choice" data-mode="syn">Đồng nghĩa<small>${SYN_LESSONS.length} bài</small></button>`;document.querySelector('.sidebar').insertBefore(modeNav,document.querySelector('.sidebar-head'));modeNav.querySelectorAll('.mode-choice').forEach(b=>b.onclick=()=>switchMode(b.dataset.mode));
const randomBtn=document.createElement('button');randomBtn.className='random-btn';randomBtn.type='button';randomBtn.textContent='⤨ Xáo bộ từ mới';randomBtn.title='Xóa lịch sử và chia lại toàn bộ từ thành các bài mới';randomBtn.onclick=resetAndShuffle;document.querySelector('.topbar').appendChild(randomBtn);
$('#mobileLessons').onchange=e=>selectLesson(e.target.value);$('#trioTab').onclick=()=>switchMode('trio');$('#synTab').onclick=()=>switchMode('syn');
function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;try{ctx.registerTool({name:'start_vocab_lesson',title:'Bắt đầu bài từ vựng',description:'Bắt đầu một bài Ghép bộ 3 hoặc Từ đồng nghĩa.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['trio','syn']},lesson:{type:'integer',minimum:1,maximum:LESSONS.length}},required:['mode','lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({mode,lesson}){const sets=mode==='trio'?LESSONS:SYN_LESSONS;if(!sets||!Number.isInteger(lesson)||lesson<1||lesson>sets.length)throw new Error('Bài học không hợp lệ');switchMode(mode);selectLesson(lesson-1);if(mode==='trio')startTrio();else startSyn();return{mode,lesson,items:sets[lesson-1].length,status:'started'}}});ctx.registerTool({name:'read_vocab_progress',title:'Xem tiến độ học',description:'Đọc thống kê riêng của cả hai chế độ.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{trio:LESSONS.map((_,i)=>({lesson:i+1,...lessonStats(i)})),synonyms:SYN_LESSONS.map((_,i)=>({lesson:i+1,...synLessonStats(i)}))}}});ctx.registerTool({name:'reshuffle_vocab_lessons',title:'Xáo lại các bài học',description:'Chia lại cả hai chế độ và xóa toàn bộ thống kê cũ. Chỉ dùng khi người học xác nhận rõ.',inputSchema:{type:'object',properties:{confirm:{type:'boolean'}},required:['confirm'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({confirm}){if(confirm!==true)throw new Error('Cần xác nhận trước khi xóa lịch sử');applyShuffle();return{trioLessons:LESSONS.length,synonymLessons:SYN_LESSONS.length,status:'reshuffled'}}})}catch{}}
renderLessonList();updateHeading();renderTrio();registerWebMCP();
